import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class GracefulShutdownServer {
    private final ExecutorService pool = Executors.newFixedThreadPool(4);

    public void start() {
        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            System.out.println("Received shutdown signal, initiating graceful teardown...");

            // Step 1: Stop accepting new tasks
            pool.shutdown(); 

            try {
                // Step 2: Wait for existing tasks to terminate
                if (!pool.awaitTermination(15, TimeUnit.SECONDS)) {
                    System.err.println("Pool did not terminate gracefully, forcing shutdown...");
                    pool.shutdownNow();

                    // Wait a bit more for tasks to respond to interruption
                    if (!pool.awaitTermination(5, TimeUnit.SECONDS)) {
                        System.err.println("Executor service failed to fully terminate.");
                    }
                }
            } catch (InterruptedException ie) {
                pool.shutdownNow();
                Thread.currentThread().interrupt();
            }

            // Step 3: Release other resources (DB pools, caches, etc.)
            System.out.println("Cleanup complete. Exiting JVM.");
        }, "app-shutdown-hook"));
    }
}
